/**
 * @file Implements an EnhancedArray class that extends the built-in Array.
 * This class inherits all standard array functionality and adds a custom
 * sum() method to calculate the sum of its numeric elements.
 */

/**
 * An enhanced Array class that adds a custom `sum()` method.
 * @extends Array
 */
class EnhancedArray extends Array {
  /**
   * Calculates and returns the sum of all numeric elements in the array.
   * It iterates through the elements, adding only those of the `number` type
   * to the total. Non-numeric elements are ignored.
   *
   * @returns {number} The sum of the numeric elements.
   */
  sum() {
    // Use the reduce method for a concise and functional approach.
    // The initial value for the accumulator (total) is 0.
    return this.reduce((total, current) => {
      // Check if the current element is a number before adding it.
      if (typeof current === 'number') {
        return total + current;
      }
      // If the element is not a number, do not change the total.
      return total;
    }, 0);
  }
}

// --- Demonstration ---

console.log("--- Step 1: Create an instance of EnhancedArray ---");
// We use the spread syntax with the constructor to create a new instance
// from an existing array literal.
const myData = [1, 2, 'a', 3, null, 4, '5', true];
const enhancedArr = new EnhancedArray(...myData);
console.log("Initial array:", enhancedArr);
console.log(`Is it an instance of EnhancedArray? ${enhancedArr instanceof EnhancedArray}`);
console.log(`Is it an instance of Array? ${enhancedArr instanceof Array}`);


console.log("\n--- Step 2: Verify that standard Array methods work ---");
enhancedArr.push(10);
console.log("After push(10):", enhancedArr);

const filteredArr = enhancedArr.filter(item => typeof item === 'number');
console.log("After filtering for numbers:", filteredArr);
// Note that methods like .filter() and .map() return a new instance of EnhancedArray
console.log(`Is the filtered result an EnhancedArray? ${filteredArr instanceof EnhancedArray}`);


console.log("\n--- Step 3: Use the new custom sum() method ---");
const totalSum = enhancedArr.sum();
console.log(`Calling .sum() on [${enhancedArr}]`);
// Expected sum: 1 + 2 + 3 + 4 + 10 = 20
console.log(`Result: ${totalSum}`);
if (totalSum === 20) {
  console.log("✅ Correct! The sum is 20.");
} else {
  console.log(`❌ Incorrect. Expected 20 but got ${totalSum}.`);
}


console.log("\n--- Step 4: Test edge cases ---");
const emptyArr = new EnhancedArray();
console.log("Sum of an empty array:", emptyArr.sum()); // Expected: 0

const noNumbersArr = new EnhancedArray('hello', 'world', { id: 1 }, false);
console.log(`Sum of [${noNumbersArr}]:`, noNumbersArr.sum()); // Expected: 0
```

### How to Run the Code

1.  Save the code above into a file named `EnhancedArray.js`.
2.  Open your terminal or command prompt.
3.  Navigate to the directory where you saved the file.
4.  Run the script using Node.js:
    ```bash
    node EnhancedArray.js
    ```

